    public class LocationEntry
    {
        public long Id { get; }
        public string Name { get; }
        public string Title { get; }
        public string Region { get; }
        public string Category { get; }

        public LocationEntry(long id, string name, string title, string region, string category)
        {
            Id = id;
            Name = name;
            Title = title;
            Region = region;
            Category = category;
        }
    }

