        /// <summary>
        /// Attempt to match a defeated entity to a boss location ID.
        /// </summary>
        public static bool TryGetBossLocation(string entityName, out long locationId)
        {
            locationId = 0;
            if (string.IsNullOrEmpty(entityName))
                return false;

            foreach (var (pattern, id) in BossLookup)
            {
                if (entityName.IndexOf(pattern, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    locationId = id;
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// Attempt to match an in-game pickup to an Archipelago location ID.
        /// Matches by exact name, title in scene, or object name.
        /// </summary>
        public static bool TryGetPickupLocation(string sceneName, string itemName, string objectName, out long locationId)
        {
            locationId = 0;
            if (string.IsNullOrEmpty(itemName) && string.IsNullOrEmpty(objectName))
                return false;

            // 1. Try matching against location Title or Name containing itemName and scene/region
            foreach (var loc in LocationsById.Values)
            {
                bool itemMatch = (!string.IsNullOrEmpty(itemName) &&
                    (loc.Title.IndexOf(itemName, StringComparison.OrdinalIgnoreCase) >= 0 ||
                     loc.Name.IndexOf(itemName, StringComparison.OrdinalIgnoreCase) >= 0));

                bool objectMatch = (!string.IsNullOrEmpty(objectName) &&
                    loc.Name.IndexOf(objectName, StringComparison.OrdinalIgnoreCase) >= 0);

                if (itemMatch || objectMatch)
                {
                    if (string.IsNullOrEmpty(sceneName) ||
                        sceneName.IndexOf(loc.Region.Replace(" ", ""), StringComparison.OrdinalIgnoreCase) >= 0 ||
                        loc.Region.IndexOf(sceneName, StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        locationId = loc.Id;
                        return true;
                    }
                }
            }

            // 2. Fallback: match by item name in any region
            if (!string.IsNullOrEmpty(itemName))
            {
                var candidate = LocationsById.Values.FirstOrDefault(l =>
                    l.Title.Equals(itemName, StringComparison.OrdinalIgnoreCase) ||
                    l.Category.Equals(itemName, StringComparison.OrdinalIgnoreCase));

                if (candidate != null)
                {
                    locationId = candidate.Id;
                    return true;
                }
            }

            return false;
        }
    }
